135:
Dans layout/theme.liquid, avant </body> (à défaut de la redirection native de Shopify Markets) :
{%- if localization.available_languages.size > 1 -%}
<script>
  (function () {
    var pref = (navigator.languages || [navigator.language])[0].slice(0, 2);
    var dispo = {{ localization.available_languages | map: "iso_code" | json }};
    var courante = "{{ localization.language.iso_code }}";
    if (pref !== courante && dispo.indexOf(pref) > -1 && !sessionStorage.getItem("langue-proposee")) {
      sessionStorage.setItem("langue-proposee", "1");
      /* proposer la version, sans redirection forcée */
      document.dispatchEvent(new CustomEvent("proposer-langue", { detail: pref }));
    }
  })();
</script>
{%- endif -%}
